/* MediFlow Simple: browser navigation, rendering, and API calls in plain JavaScript. */
(function () {
  'use strict';

  // The version is also included in index.html's script URL to prevent an old
  // browser-cached bundle from surviving a deployment.
  window.__MEDIFLOW_BUILD__ = '2026-10-17-v2';

  const app = document.getElementById('app');
  const roleMenus = {
    admin: [['OVERVIEW', [['Dashboard','dashboard'],['Analytics','analytics']]], ['MANAGEMENT', [['Doctors','doctors'],['Receptionists','receptionists'],['Patients','patients'],['Appointments','appointments'],['Departments','departments'],['Queries','queries']]], ['SYSTEM', [['Notifications','notifications'],['Settings','settings']]]],
    doctor: [['WORKSPACE', [['Dashboard','dashboard'],['Appointments','appointments'],['Patients','patients'],['Consultation','consultation'],['Prescriptions','prescriptions'],['Queries','queries'],['My profile','profile']]]],
    reception: [['FRONT DESK', [['Dashboard','dashboard'],['Patient registration','patient-registration'],['Patients','patients'],['Appointments','appointments'],['Prescriptions','prescriptions'],['Queries','queries'],['Billing','billing'],['Notifications','notifications'],['My profile','profile']]]],
    patient: [['MY HEALTH', [['Dashboard','dashboard'],['My profile','profile'],['Appointments','appointments'],['Book appointment','book'],['Prescriptions','prescriptions'],['Medical history','history'],['Messages & queries','queries'],['Notifications','notifications']]]]
  };
  const titles = {dashboard:'Dashboard',doctors:'Doctor management',receptionists:'Receptionist management',patients:'Patients',appointments:'Appointments',departments:'Departments',queries:'Patient queries',analytics:'Clinic analytics',notifications:'Notifications',settings:'Settings',profile:'My profile',consultation:'Consultation',prescriptions:'Prescriptions',history:'Medical history',book:'Book an appointment','patient-registration':'Patient registration',billing:'Billing & formalities'};
  const descriptions = {dashboard:'Here’s what’s happening across your care today.',appointments:'Review schedules, requests, and appointment outcomes.',patients:'Find and manage patient records in one place.',prescriptions:'Track doctor-authored prescriptions and processing status.',queries:'Keep every patient conversation moving toward resolution.',analytics:'A clear view of clinic activity and service trends.',notifications:'Stay up to date with the latest clinic activity.',history:'A timeline of your visits and care plan.',book:'Request a visit with the right care team.','patient-registration':'Capture patient details and verify registrations.',billing:'Manage visit fees and print receipts.',settings:'Manage clinic preferences and your workspace.'};
  const state = { user:null, store:null, search:'', filter:'All', selected:null, modal:null, toastTimer:null, slideTimer:null, mobile:false, theme:localStorage.getItem('mf_dark')==='1', slide:0 };
  const slides = [
    {eyebrow:'Care that stays connected',title:'Good care begins<br>with a better conversation.',copy:'From your first appointment to the next step in your care, people and information stay connected.',image:'https://images.unsplash.com/photo-1758691462878-6edc3d3da1be?auto=format&fit=crop&w=2200&q=85',label:'Thoughtful consultations, clear next steps'},
    {eyebrow:'A team around your care',title:'Specialist care,<br>with the whole picture in view.',copy:'Meet a clinician who listens, reviews your history and helps you understand what comes next.',image:'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?auto=format&fit=crop&w=2200&q=85',label:'Experienced clinicians. One coordinated team.'},
    {eyebrow:'Your visit, made easier',title:'From appointment<br>to follow-up, together.',copy:'Book a visit, keep track of the details and reach the clinic team through one patient-friendly portal.',image:'https://images.unsplash.com/photo-1764885517847-79d62138cc58?auto=format&fit=crop&w=2200&q=85',label:'A calm, considered experience at every step'}
  ];
  const departmentsText = [
    ['Cardiology','Heart health, risk review and ongoing cardiovascular care.','https://images.unsplash.com/photo-1628348068343-c6a848d2b6dd?auto=format&fit=crop&w=1000&q=80'],
    ['General medicine','Everyday health concerns, preventive care and continuity.','https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=1000&q=80'],
    ['Orthopedics','Practical support for movement, joints and recovery.','https://images.unsplash.com/photo-1584820927498-cfe5211fd8bf?auto=format&fit=crop&w=1000&q=80'],
    ['Dermatology','Thoughtful assessment and care for skin, hair and nails.','https://images.unsplash.com/photo-1616394584738-fc6e612e71b9?auto=format&fit=crop&w=1000&q=80']
  ];

  function escapeHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, (character) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
  }
  function initials(value) { return String(value || '').split(/\s+/).filter(Boolean).slice(0,2).map((part)=>part.charAt(0)).join('').toUpperCase(); }
  function slug(value) { return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g,'-'); }
  function today() { return new Date().toISOString().slice(0,10); }
  function icon(mark) { return '<span class="brand-mark" aria-hidden="true">' + mark + '</span>'; }
  function navTo(path) { history.pushState({},'',path); state.search='';state.filter='All';state.selected=null;state.modal=null;render();window.scrollTo(0,0); }
  async function api(path, options) {
    const settings=options||{};
    const response=await fetch('/api'+path,{method:settings.method||'GET',credentials:'same-origin',headers:{'Content-Type':'application/json',...(settings.headers||{})},body:settings.body===undefined?undefined:JSON.stringify(settings.body)});
    const result=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(result.error||'The request could not be completed.');
    return result;
  }
  function notify(message) {
    const region=document.getElementById('toast-region');
    region.innerHTML='<div class="toast" role="status">✓ '+escapeHtml(message)+'</div>';
    clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>{region.innerHTML='';},3500);
  }
  async function saveChanges(changes, message) {
    await api('/app/changes',{method:'POST',body:{changes}});
    await reloadStore();render();if(message)notify(message);
  }
  async function reloadStore() { const result=await api('/app/bootstrap');state.store=result.store; }

  async function render() {
    const pathname=decodeURIComponent(location.pathname);
    if(!['/','/about','/doctors','/departments','/services','/expertise','/patients','/contact'].includes(pathname)){clearInterval(state.slideTimer);state.slideTimer=null;}
    if(pathname==='/login'){renderLogin();return;}
    if(pathname==='/register'){renderRegistration();return;}
    if(pathname==='/'||['/about','/doctors','/departments','/services','/expertise','/patients','/contact'].includes(pathname)){
      const [doctorResult,departmentResult]=await Promise.all([api('/doctors').catch(()=>({doctors:[]})),api('/departments').catch(()=>({departments:[]}))]);
      renderLanding(doctorResult.doctors,departmentResult.departments);return;
    }
    const segments=pathname.split('/').filter(Boolean);const role=segments[0];const page=segments[1]||'dashboard';
    if(!roleMenus[role]){navTo('/');return;}
    try{
      if(!state.user){const result=await api('/auth/me');state.user=result.user;}
      const currentRole=state.user.role.toLowerCase();
      if(currentRole!==role){navTo('/'+currentRole+'/dashboard');return;}
      await reloadStore();
      renderWorkspace(role,page,segments[2]||'');
    }catch(error){state.user=null;state.store=null;navTo('/login');}
  }

  function renderLogin(message) {
    app.innerHTML='<div class="login-wrap"><section class="login-hero"><div class="brand">'+icon('♥')+'MediFlow</div><h1>Care that moves with you.</h1><p style="max-width:430px;color:#c4d9df;line-height:1.7">One connected workspace for clinic teams and the people they care for.</p><div class="row" style="gap:20px;margin-top:28px;color:#d8e8ea"><span>♢ Secure patient portal</span><span>⌁ Connected care</span></div></section><section class="login-panel"><div class="login-card"><div class="eyebrow">Welcome to MediFlow</div><h2>Sign in to your account</h2><p class="subtext" style="margin-bottom:25px">Use your registered clinic or patient account.</p><form data-form="login"><div class="field"><label for="email">Email address</label><input id="email" name="email" class="input" type="email" autocomplete="username" required placeholder="name@clinic.com"></div><div class="field"><label for="password">Password</label><input id="password" name="password" class="input" type="password" autocomplete="current-password" required placeholder="Enter your password"></div><p class="form-error" role="alert">'+escapeHtml(message||'')+'</p><button class="btn primary" type="submit" style="width:100%">Sign in <span aria-hidden="true">→</span></button></form><p class="muted small" style="margin-top:20px;text-align:center">New patient? <a href="/register" data-route="/register">Create a patient account</a></p><p class="muted" style="font-size:10px;margin-top:18px;text-align:center">Academic demo · synthetic data only</p></div></section></div>';
  }
  function renderRegistration(message) {
    app.innerHTML='<div class="login-wrap"><section class="login-hero"><div class="brand">'+icon('♥')+'MediFlow</div><h1>Your care, all in one place.</h1><p style="max-width:430px;color:#c4d9df;line-height:1.7">Create your patient portal account to request appointments and stay in touch with the clinic.</p></section><section class="login-panel"><div class="login-card"><div class="eyebrow">Patient portal</div><h2>Create your account</h2><p class="subtext" style="margin-bottom:20px">Registration creates a patient account for clinic review.</p><form data-form="register"><div class="field"><label>Full name</label><input class="input" name="name" required maxlength="160" autocomplete="name"></div><div class="grid two-col"><div class="field"><label>Date of birth</label><input class="input" type="date" name="dob" required max="'+today()+'"></div><div class="field"><label>Gender</label><select class="select" name="gender" required><option value="">Select</option><option>Female</option><option>Male</option><option>Non-binary</option><option>Prefer not to say</option></select></div></div><div class="field"><label>Phone</label><input class="input" name="phone" type="tel" required minlength="7" maxlength="60" autocomplete="tel"></div><div class="field"><label>Email address</label><input class="input" name="email" type="email" required maxlength="254" autocomplete="email"></div><div class="field"><label>Password (at least 12 characters)</label><input class="input" name="password" type="password" required minlength="12" maxlength="200" autocomplete="new-password"></div><details style="margin:0 0 12px"><summary class="small">Optional details</summary><div class="field" style="margin-top:12px"><label>Blood group</label><select class="select" name="blood"><option value="">Select</option><option>A+</option><option>A-</option><option>B+</option><option>B-</option><option>AB+</option><option>AB-</option><option>O+</option><option>O-</option></select></div><div class="field"><label>Address</label><input class="input" name="address" maxlength="400"></div><div class="field"><label>Emergency contact</label><input class="input" name="emergency" maxlength="240"></div><div class="field"><label>Identification details</label><input class="input" name="identification" maxlength="100"></div></details><p class="form-error" role="alert">'+escapeHtml(message||'')+'</p><button class="btn primary" type="submit" style="width:100%">Create patient account</button></form><p class="muted small" style="margin-top:18px;text-align:center">Already registered? <a href="/login" data-route="/login">Sign in</a></p></div></section></div>';
  }

  function renderLanding(doctors, dbDepartments) {
    const doctorList=Array.isArray(doctors)?doctors:[];
    const departmentList=Array.isArray(dbDepartments)?dbDepartments:[];
    const sections=departmentsText.map((d,i)=>'<a href="#care-team" class="site-department-card dept-'+(i+1)+'"><div class="site-department-image"><img src="'+d[2]+'" alt="Care in '+escapeHtml(d[0])+'"><span class="site-department-number">0'+(i+1)+'</span></div><div class="site-department-copy"><h3>'+escapeHtml(d[0])+'</h3><p>'+escapeHtml(d[1])+'</p><span class="site-text-link">Explore department ↗</span></div></a>').join('');
    const doctorCards=doctorList.map((d,i)=>'<article class="site-doctor-card"><div class="site-doctor-photo"><img src="'+['https://images.unsplash.com/photo-1559839734-2b71ea197ec2?auto=format&fit=crop&w=760&q=80','https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?auto=format&fit=crop&w=760&q=80','https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=760&q=80','https://images.unsplash.com/photo-1594824476967-48c8b964273f?auto=format&fit=crop&w=760&q=80'][i%4]+'" alt="Portrait representing '+escapeHtml(d.name)+'"><span class="site-doctor-status"><i></i>'+escapeHtml(d.status||'Accepting appointments')+'</span></div><div class="site-doctor-info"><span class="site-doctor-specialty">'+escapeHtml(d.department||d.specialty||'Care team')+'</span><h3>'+escapeHtml(d.name||'MediFlow clinician')+'</h3><p>'+escapeHtml(d.specialty||'Connected clinical care')+(d.experience?' · '+escapeHtml(d.experience)+' experience':'')+'</p><p class="site-doctor-bio">'+escapeHtml(d.bio||'Meet with a clinician who listens, reviews your history and helps you understand what comes next.')+'</p><div class="site-doctor-actions"><a href="/login" data-route="/login">View profile ↗</a><a href="/login" data-route="/login">Book a visit →</a></div><span class="site-demo-disclaimer">Synthetic clinician for academic demo</span></div></article>').join('');
    const filterDepartments=departmentList.length?departmentList.map(d=>d.name).filter(Boolean):departmentsText.map(d=>d[0]);
    const departmentOptions=Array.from(new Set(filterDepartments)).map(name=>'<option value="'+escapeHtml(name)+'">'+escapeHtml(name)+'</option>').join('');

    app.innerHTML=`
      <main class="site-shell">
        <div class="site-utility"><div class="site-container site-utility-inner"><span>◷ Mon–Fri, 8:00 am–6:00 pm · Saturday, 9:00 am–1:00 pm</span><span class="site-utility-right"><a href="tel:+15558002400">☎ +1 (555) 800-2400</a><span class="site-demo">Academic demo · fictional clinic</span></span></div></div>
        <header class="site-header"><div class="site-container site-header-inner">
          <a class="site-brand" href="/" aria-label="MediFlow home"><span class="site-brand-mark">♥</span><span>MediFlow<small>FAMILY CLINIC</small></span></a>
          <nav class="site-nav" aria-label="Main navigation"><a href="#home">Home</a><a href="#about">About</a><a href="#care-team">Doctors</a><a href="#expertise">Departments</a><a href="#services">Services</a><a href="#expertise">Expertise</a><a href="#patient-stories">Patients</a><a href="#contact">Contact</a></nav>
          <div class="site-header-actions"><a href="tel:+15558002400" class="site-call">☎ <span><small>Speak with our team</small>+1 (555) 800-2400</span></a><button class="site-icon-button site-search-button" type="button" aria-label="Find a doctor" data-action="find-doctors">⌕</button><a href="/login" class="site-login" data-route="/login">Patient login</a><a href="/login" class="site-button site-button-dark" data-route="/login">Book an appointment ↗</a></div>
          <button class="site-mobile-toggle" type="button" aria-label="Open menu" aria-expanded="false" data-action="public-menu">☰</button>
        </div></header>
        <section id="home" class="site-hero">
          <div class="site-hero-photo"><img id="hero-image" src="${slides[state.slide].image}" alt="${escapeHtml(slides[state.slide].eyebrow)}"></div><div class="site-hero-shade"></div>
          <div class="site-container site-hero-content"><div class="site-hero-copy"><span id="hero-eyebrow" class="site-overline site-overline-light"><i></i>${escapeHtml(slides[state.slide].eyebrow)}</span><h1 id="hero-title">${slides[state.slide].title}</h1><p id="hero-copy">${escapeHtml(slides[state.slide].copy)}</p><div class="site-hero-actions"><button class="site-button site-button-cream" type="button" data-action="find-doctors">Find a doctor →</button><a class="site-button site-button-outline" href="/login" data-route="/login">Book an appointment　▦</a></div><div class="site-hero-proof"><span class="site-proof-icon">✓</span><span><strong>One connected care team</strong><small>Appointments, visit notes and follow-up in one place</small></span></div></div>
            <div class="site-hero-caption"><span class="site-caption-rule"></span><span id="hero-label">${escapeHtml(slides[state.slide].label)}</span></div>
            <div class="site-carousel-controls"><div class="site-carousel-count"><span id="hero-count">0${state.slide+1}</span><i></i>0${slides.length}</div><button class="site-icon-button" type="button" aria-label="Previous image" data-action="slide-prev">←</button><button class="site-icon-button" type="button" aria-label="Next image" data-action="slide-next">→</button></div>
          </div><div class="site-hero-dots" role="tablist" aria-label="Featured care stories">${slides.map((item,i)=>'<button type="button" role="tab" aria-label="Show slide '+(i+1)+': '+escapeHtml(item.eyebrow)+'" aria-selected="'+(i===state.slide)+'" class="'+(i===state.slide?'active':'')+'" data-action="slide" data-slide="'+i+'"></button>').join('')}</div><div class="site-hero-side-note">Care, connected from the first hello.</div>
        </section>
        <section class="site-intro-strip"><div class="site-container site-intro-inner"><div><span class="site-overline"><i></i>MediFlow, at a glance</span><h2>Good care is a team effort.</h2></div><p>Thoughtful clinicians, an attentive front desk and a patient portal designed to keep the practical details close at hand.</p><a href="#about" class="site-text-link">Get to know us →</a></div></section>
        <section class="site-section site-trust"><div class="site-container"><div class="site-section-heading site-heading-center"><span class="site-overline"><i></i>A considered standard of care</span><h2>Trusted care, built around people.</h2><p>Illustrative figures for the MediFlow academic project — not real-world clinic claims.</p></div><div class="site-metrics"><div><strong>25<span>+</span></strong><small>Years of combined<br>clinical experience</small></div><div><strong>50<span>+</span></strong><small>Specialist clinicians<br>in our demo network</small></div><div><strong>20<span>+</span></strong><small>Care pathways<br>to explore</small></div><div><strong>10k<span>+</span></strong><small>Patient visits<br>represented in demo</small></div></div><div class="site-recognition"><div class="site-recognition-title">✧ <span>Recognized for excellence<small>Academic project · illustrative recognitions</small></span></div>${['Patient-centered care','Digital health innovation','Quality of experience','Community wellness'].map(x=>'<div class="site-recognition-item"><span class="site-award-icon">✦</span><span>'+x+'<small>Demo recognition</small></span></div>').join('')}</div></div></section>
        <section id="about" class="site-section site-about"><div class="site-container site-about-grid"><div class="site-about-image"><img src="https://images.unsplash.com/photo-1764885517847-79d62138cc58?auto=format&fit=crop&w=1400&q=85" alt="Modern clinic exterior with a bright, welcoming glass entrance"><div class="site-image-note"><span class="site-note-icon">♡</span><span><strong>A more connected visit</strong><small>Care that keeps the next step in view</small></span></div></div><div class="site-about-copy"><span class="site-overline"><i></i>A clinic designed around you</span><h2>Medicine is personal.<br><em>Your care experience should be, too.</em></h2><p class="site-lead">At MediFlow, a good visit is more than a conversation in the exam room. It is a team that knows what comes next — and helps you feel ready for it.</p><p>Our academic clinic model brings patient registration, appointment coordination, clinical notes and follow-up communication into one considered experience.</p><div class="site-about-points"><div><span>✓</span><strong>People first<small>Care teams who make space to listen.</small></strong></div><div><span>✓</span><strong>Clear next steps<small>Visit details stay easy to find.</small></strong></div><div><span>✓</span><strong>Connected support<small>Practical questions reach the right team.</small></strong></div></div><a href="#care-journey" class="site-text-link">How the experience works →</a></div></div></section>
        <section id="expertise" class="site-section site-expertise"><div class="site-container"><div class="site-section-heading site-heading-row"><div><span class="site-overline"><i></i>Our expertise</span><h2>Care for the moments<br>that matter.</h2></div><p>Explore the specialties available in the MediFlow demo clinic. Each is part of a coordinated visit experience.</p></div><div class="site-department-grid">${sections}</div><div class="site-department-foot"><span>${departmentList.length?departmentList.length+' departments available in the clinic directory.':'More specialties are planned for future project iterations.'}</span><a href="#services" class="site-text-link">View all services →</a></div></div></section>
        <section id="services" class="site-section site-services"><div class="site-container site-services-grid"><div class="site-services-intro"><span class="site-overline site-overline-light"><i></i>Services & support</span><h2>Help at every<br>step of the visit.</h2><p>From a quick question to a planned consultation, the clinic team helps the details move smoothly.</p><a href="/login" class="site-button site-button-cream" data-route="/login">Visit the patient portal →</a></div><div class="site-services-list">${[['01','Specialist consultation','Meet with a clinician and discuss the care that is right for you.'],['02','Preventive health','Keep routine care and wellness conversations on your calendar.'],['03','Visit coordination','Appointment requests and schedule changes handled with care.'],['04','Prescription follow-through','Doctor-authored plans, with clear processing updates for patients.'],['05','Patient portal','Review appointments, visit history and clinic messages in one place.']].map(([n,title,text])=>'<div class="site-service-row"><span>'+n+'</span><div><h3>'+title+'</h3><p>'+text+'</p></div><span aria-hidden="true">↗</span></div>').join('')}</div></div></section>
        <section id="care-team" class="site-section site-doctors"><div class="site-container"><div class="site-section-heading site-heading-row"><div><span class="site-overline"><i></i>Meet the care team</span><h2>Care starts with a<br>good conversation.</h2></div><p>Meet the synthetic clinicians in our demo clinic. Choose a department or search by name to find a match.</p></div><div class="site-doctor-toolbar"><span class="site-finder-label">⌕ Find a clinician</span><label class="site-doctor-search">⌕ <input id="doctor-search" aria-label="Search doctors by name or specialty" placeholder="Search doctors or specialties"></label><label class="site-filter-select"><span class="sr-only">Filter by department</span><select id="doctor-department" aria-label="Filter by department"><option value="All departments">All departments</option>${departmentOptions}</select><span aria-hidden="true">⌄</span></label><span class="site-results-count">${doctorList.length} clinicians</span></div><div class="site-doctor-grid" id="doctor-grid">${doctorCards}</div><div class="site-no-results"${doctorList.length?' hidden':''}>${doctorList.length?'No clinicians match that search. Try another name or department.':'Our care team directory is being updated. Please contact the clinic for help choosing a department.'}</div></div></section>
        <section id="care-journey" class="site-section site-journey"><div class="site-container"><div class="site-section-heading site-heading-center"><span class="site-overline"><i></i>One connected experience</span><h2>A clear path through your care.</h2><p>The patient journey in MediFlow, from the first details to the next appointment.</p></div><div class="site-journey-grid">${[['01','Register','Share your details once so the clinic team can prepare for your visit.'],['02','Book a visit','Choose a department, clinician and time that works for you.'],['03','Meet your doctor','Discuss your concerns and review the information that matters.'],['04','Receive your plan','Your doctor records the diagnosis, notes and prescription.'],['05','Stay in touch','Reception keeps visit details moving and answers practical questions.'],['06','Plan follow-up','Keep your visit history and next steps together in your portal.']].map(([n,title,text],i)=>'<div class="site-journey-step"><span class="site-step-number">'+n+'</span>'+(i<5?'<span class="site-step-line"></span>':'')+'<h3>'+title+'</h3><p>'+text+'</p></div>').join('')}</div></div></section>
        <section class="site-section site-recognition-band"><div class="site-container site-recognition-band-inner"><div><span class="site-overline"><i></i>Care, with a human touch</span><h2>Good health is a relationship.</h2></div><div class="site-recognition-quote"><span>“</span><p>We want every patient to leave a visit knowing what was discussed, what happens next, and who to contact with a question.</p><small>MediFlow care team · demo statement</small></div></div></section>
        <section id="patient-stories" class="site-section site-stories"><div class="site-container site-stories-grid"><div class="site-stories-heading"><span class="site-overline"><i></i>Patient experience</span><h2>Care is remembered<br>in the little things.</h2><p>Fictional patient stories created for the MediFlow academic project.</p><div class="site-story-arrows"><button type="button" aria-label="Previous patient story">←</button><button type="button" aria-label="Next patient story">→</button></div></div><article class="site-review-card"><div class="site-review-top"><div class="site-review-avatar">RW</div><div><strong>Riya W.</strong><small>Specialist consultation · Patient story · demo</small></div><div class="site-stars" aria-label="5 out of 5 stars">★★★★★</div></div><blockquote>“The appointment process was simple. I could follow my visit notes and prescription without having to search through messages.”</blockquote><div class="site-review-bottom"><span>Illustrative testimonial · not a real patient</span><div><button type="button" class="active" aria-label="Show review 1"></button><button type="button" aria-label="Show review 2"></button><button type="button" aria-label="Show review 3"></button></div></div></article></div></section>
        <section id="contact" class="site-contact"><div class="site-container site-contact-inner"><div><span class="site-overline site-overline-light"><i></i>We’re here to help</span><h2>Need to speak<br>with a clinician?</h2><p>Find a department, request an appointment or call the clinic team with a practical question.</p><div class="site-contact-actions"><button class="site-button site-button-cream" type="button" data-action="find-doctors">Find a doctor →</button><a href="/login" class="site-button site-button-outline" data-route="/login">Book an appointment ▦</a></div></div><div class="site-contact-card"><div><span>⌖</span><span><strong>Visit the clinic</strong><small>180 Harbor Street<br>Brookfield, Demo District</small></span></div><div><span>☎</span><span><strong>Call the front desk</strong><a href="tel:+15558002400">+1 (555) 800-2400</a></span></div><div><span>◷</span><span><strong>Clinic hours</strong><small>Mon–Fri, 8:00 am–6:00 pm<br>Saturday, 9:00 am–1:00 pm</small></span></div><small class="site-contact-emergency">For emergencies, contact your local emergency services.</small></div></div></section>
        <footer class="site-footer"><div class="site-container"><div class="site-footer-main"><div class="site-footer-brand"><a class="site-brand site-brand-footer" href="/" aria-label="MediFlow home"><span class="site-brand-mark">♥</span><span>MediFlow<small>FAMILY CLINIC</small></span></a><p>Connected care for every stage of your visit — from appointment booking to follow-up.</p><span class="site-footer-demo">◇ Academic project · all people and figures are fictional</span></div><div class="site-footer-links"><div><strong>Explore</strong><a href="#about">About MediFlow</a><a href="#care-team">Our doctors</a><a href="#expertise">Departments</a><a href="#services">Services</a></div><div><strong>For patients</strong><a href="/login" data-route="/login">Patient portal</a><a href="/login" data-route="/login">Appointments</a><a href="/login" data-route="/login">Visit history</a><a href="#contact">Contact the clinic</a></div><div><strong>Contact</strong><a href="tel:+15558002400">+1 (555) 800-2400</a><span>180 Harbor Street<br>Brookfield, Demo District</span><span>Mon–Fri · 8:00 am–6:00 pm</span></div></div></div><div class="site-footer-bottom"><span>© 2026 MediFlow · Academic demonstration only</span><div><a href="#contact">Privacy</a><a href="#contact">Terms</a><a href="#home">Back to top ↗</a></div></div></div></footer>
      </main>`;
    bindLanding();
  }

  function bindLanding(){
    clearInterval(state.slideTimer);state.slideTimer=setInterval(()=>showHeroSlide(state.slide+1),7500);
    const search=document.getElementById('doctor-search'),select=document.getElementById('doctor-department'),grid=document.getElementById('doctor-grid');
    if(search&&select&&grid){const filterDoctors=()=>{const needle=search.value.toLowerCase();const department=select.value;const cards=Array.from(grid.querySelectorAll('.site-doctor-card'));let count=0;cards.forEach((card)=>{const matches=card.textContent.toLowerCase().includes(needle)&&(department==='All departments'||card.textContent.toLowerCase().includes(department.toLowerCase()));card.hidden=!matches;if(matches)count++;});const label=app.querySelector('.site-results-count');if(label)label.textContent=count+' clinicians';const empty=app.querySelector('.site-no-results');if(empty)empty.hidden=count>0;};search.addEventListener('input',filterDoctors);select.addEventListener('change',filterDoctors);}
  }

  function workspaceNav(role,page){
    return roleMenus[role].map((group)=>'<div class="nav-label">'+group[0]+'</div>'+group[1].map((item)=>'<a data-route="/'+role+'/'+item[1]+'" class="nav-link '+(item[1]===page?'active':'')+'" href="/'+role+'/'+item[1]+'"><span aria-hidden="true">'+navIcon(item[1])+'</span>'+item[0]+(item[1]==='notifications'&&state.store.notifications.some(n=>!n.read)?'<span class="nav-count">•</span>':'')+'</a>').join('')).join('');
  }
  function navIcon(page){return ({dashboard:'⌂',analytics:'▥',doctors:'✚',receptionists:'♙',patients:'♧',appointments:'▦',departments:'▤',queries:'▱',notifications:'♧',settings:'⚙',profile:'♙',consultation:'☷',prescriptions:'▤',history:'◷',book:'＋','patient-registration':'♙',billing:'＄'})[page]||'•';}
  function renderWorkspace(role,page,detailId){
    const title=titles[page]||page;const workspaceName={admin:'Clinic administration',doctor:'Clinical workspace',reception:'Front desk workspace',patient:'Patient portal'}[role];
    app.innerHTML='<div class="app '+(state.theme?'dark':'')+'"><aside class="sidebar '+(state.mobile?'open':'')+'"><div class="brand">'+icon('♥')+'MediFlow</div>'+workspaceNav(role,page)+'<div class="sidebar-bottom"><div class="row" style="padding:6px 8px"><div class="avatar" style="background:#2b5966;color:white">'+initials(state.user.name)+'</div><div style="flex:1;min-width:0"><div class="small" style="font-weight:650">'+escapeHtml(state.user.name)+'</div><div class="small muted" style="text-transform:capitalize">'+(role==='reception'?'Receptionist':role)+'</div></div><button class="btn ghost" data-action="logout" title="Sign out">↪</button></div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="btn ghost mobile-menu" data-action="mobile">☰</button><div class="muted small hide-mobile">'+workspaceName+' <span style="padding:0 8px">/</span><strong>'+escapeHtml(title)+'</strong></div></div><div class="top-actions"><button class="btn ghost" data-action="theme" title="Toggle theme">'+(state.theme?'☼':'◐')+'</button><a data-route="/'+role+'/notifications" class="btn ghost" href="/'+role+'/notifications" aria-label="Notifications">♧</a><div class="avatar" title="'+escapeHtml(state.user.name)+'">'+initials(state.user.name)+'</div></div></header><section class="content"><div class="page-head"><div><div class="eyebrow">'+workspaceName+'</div><h1 class="page-title">'+(page==='dashboard'?'Good '+(new Date().getHours()<12?'morning':'afternoon')+', '+escapeHtml(state.user.name.split(' ')[0]):escapeHtml(title))+'</h1><p class="subtext">'+(descriptions[page]||'Review your MediFlow workspace and care records.')+'</p></div>'+createPageAction(role,page)+'</div>'+renderPage(role,page,detailId)+'</section></main></div>'+renderModal();
  }
  function createPageAction(role,page){const allowed=(page==='patients'&&['admin','reception'].includes(role))||(['doctors','receptionists','departments'].includes(page)&&role==='admin');if(allowed)return '<button class="btn primary" data-action="create">＋ Add '+(titles[page]||'record').replace(' management','').toLowerCase()+'</button>';return '';}
  function card(title,body,action){return '<section class="card"><div class="row between" style="margin-bottom:14px"><h2 class="section-title">'+title+'</h2>'+(action||'')+'</div>'+body+'</section>';}
  function stat(label,value,delta,mark){return '<div class="card stat"><div><div class="stat-label">'+label+'</div><div class="stat-value">'+escapeHtml(value)+'</div><div class="small muted" style="margin-top:6px">'+(delta||'')+'</div></div><div class="stat-icon">'+mark+'</div></div>';}
  function badge(value){return '<span class="badge '+slug(value)+'">'+escapeHtml(value||'—')+'</span>';}
  function person(value,id){return '<span class="person"><span class="avatar">'+initials(value)+'</span><span><strong>'+escapeHtml(value)+'</strong><br><span class="muted small">'+escapeHtml(id||'')+'</span></span></span>';}
  function renderPage(role,page,detailId){
    const s=state.store;const patientId=state.user.patientId||s.patients.find(p=>p.email===state.user.email)?.id;
    const patientAppointments=s.appointments.filter(a=>a.patientId===patientId);const doctorAppointments=s.appointments.filter(a=>a.doctor===state.user.name||s.doctors.find(d=>d.email===state.user.email&&d.name===a.doctor));
    const appointments=role==='patient'?patientAppointments:role==='doctor'?doctorAppointments:s.appointments;
    const prescriptions=role==='patient'?s.prescriptions.filter(x=>x.patientId===patientId&&x.status==='Available'):role==='doctor'?s.prescriptions.filter(x=>x.doctor===state.user.name):s.prescriptions;
    const queries=role==='patient'?s.queries.filter(x=>x.patientId===patientId):role==='doctor'?s.queries.filter(x=>x.status==='Forwarded to Doctor'):s.queries;
    if(page==='dashboard'){
      const pending=s.appointments.filter(a=>a.status==='Pending').length;const todayAppointments=appointments.filter(a=>a.date===today()).length;
      let stats=[];
      if(role==='admin')stats=[stat('Total patients',s.patients.length,'Clinic records','♧'),stat('Doctors',s.doctors.length,'Across specialties','✚'),stat('Today’s appointments',todayAppointments,'Clinic schedule','▦'),stat('Pending requests',pending,'Needs review','◷')];
      if(role==='doctor')stats=[stat('Today’s appointments',todayAppointments,'Your schedule','▦'),stat('Pending consultations',doctorAppointments.filter(a=>a.status==='Confirmed').length,'Ready to begin','☷'),stat('Completed visits',s.consultations.filter(c=>c.doctor===state.user.name).length,'Recorded visits','✓'),stat('Follow-ups',s.consultations.filter(c=>c.doctor===state.user.name&&c.followup).length,'Care plan notes','◷')];
      if(role==='reception')stats=[stat('Today’s appointments',todayAppointments,'Across all clinicians','▦'),stat('Waiting patients',s.appointments.filter(a=>a.status==='Confirmed'&&a.date===today()).length,'At the front desk','◷'),stat('New registrations',s.patients.filter(p=>p.status==='Pending').length,'Verification needed','♧'),stat('Pending prescriptions',s.prescriptions.filter(p=>p.status==='Awaiting processing').length,'Ready to process','▤')];
      if(role==='patient')stats=[stat('Next appointment',patientAppointments.some(a=>a.status==='Confirmed')?'1':'—','Check your schedule','▦'),stat('Active prescriptions',prescriptions.length,'Ready in your portal','▤'),stat('Open queries',queries.filter(q=>q.status!=='Resolved').length,'Care team replies here','▱'),stat('Visits this year',s.consultations.filter(c=>c.patientId===patientId).length,'Your care timeline','♥')];
      const activity=role==='doctor'?renderQueryList(queries.slice(0,4)):renderNotifications(s.notifications.slice(0,4),role,false);
      return '<div class="grid stats">'+stats.join('')+'</div><div class="grid two-col">'+card(role==='patient'?'Your upcoming care':role==='doctor'?'Today’s schedule':role==='reception'?'Today at the front desk':'Appointment overview',renderAppointmentList(role==='patient'?patientAppointments:role==='doctor'?doctorAppointments:s.appointments,role),'<a class="small" data-route="/'+role+'/appointments" href="/'+role+'/appointments">View schedule →</a>')+card(role==='doctor'?'Patient queries needing input':role==='reception'?'Needs your attention':'Recent activity',activity,'<a class="small" data-route="/'+role+'/'+(role==='doctor'||role==='reception'?'queries':'notifications')+'" href="/'+role+'/'+(role==='doctor'||role==='reception'?'queries':'notifications')+'">View all →</a>')+'</div>'+(role==='admin'?'<div class="grid two-col" style="margin-top:18px">'+card('Appointment statistics',bars(['Mon','Tue','Wed','Thu','Fri','Sat'],[7,10,8,13,9,5]))+card('Doctor workload',s.doctors.map(d=>'<div class="bar-row"><span>'+escapeHtml(d.name)+'</span><div class="bar-bg"><div class="bar-fill" style="width:65%"></div></div><strong>'+d.patients+'</strong></div>').join(''))+'</div>':'');
    }
    if(page==='analytics')return renderAnalytics(s);
    if(page==='settings')return renderSettings(s);
    if(page==='profile')return renderProfile(role,s);
    if(page==='consultation')return renderConsultationForm(s,doctorAppointments);
    if(page==='book')return renderAppointmentForm(s);
    if(page==='patient-registration')return renderPatientForm(s);
    if(page==='history')return '<div class="card"><div class="timeline">'+s.consultations.filter(c=>c.patientId===patientId).map(c=>'<div class="timeline-item"><div class="row between"><strong>'+escapeHtml(c.diagnosis)+'</strong><span class="muted small">'+escapeHtml(c.date)+'</span></div><div class="muted small" style="margin:5px 0">'+escapeHtml(c.doctor)+' · '+escapeHtml(c.symptoms)+'</div><p>'+escapeHtml(c.notes)+'</p><div class="small" style="color:#147d83">Follow-up: '+escapeHtml(c.followup||'—')+'</div></div>').join('')||'<div class="empty">Your visit history will appear here.</div>'+'</div></div>';
    if(page==='billing')return renderBilling(s);
    if(page==='notifications')return '<div class="row between" style="margin-bottom:15px"><span class="muted small">'+s.notifications.filter(n=>!n.read).length+' unread notifications</span><button class="btn" data-action="read-all">Mark all as read</button></div><div class="card" style="padding:4px 20px">'+renderNotifications(s.notifications,role,true)+'</div>';
    if(page==='prescriptions')return '<div class="card"><div class="toolbar"><input class="input search-input" style="max-width:330px" placeholder="Search prescriptions" value="'+escapeHtml(state.search)+'">'+(role==='doctor'?'<a href="/doctor/consultation" data-route="/doctor/consultation" class="btn primary">＋ New prescription</a>':'')+'</div>'+renderPrescriptionList(prescriptions,role)+'</div>';
    if(page==='queries')return renderQueries(queries,role);
    if(page==='appointments')return renderCollectionTable('appointments',appointments,role);
    if(page==='patients'&&role==='doctor'&&detailId)return renderPatientDetail(detailId,s);
    if(['patients','doctors','receptionists','departments'].includes(page))return renderCollectionTable(page,s[page],role);
    return '<div class="card empty"><div class="empty-icon">⌁</div>Page is ready for your role.</div>';
  }
  function bars(labels,values){const max=Math.max(1,...values);return '<div style="display:flex;align-items:end;gap:14px;height:180px;padding-top:10px">'+values.map((v,i)=>'<div style="flex:1;text-align:center;height:100%;display:flex;flex-direction:column;justify-content:end;gap:8px"><span class="small muted">'+v+'</span><div class="bar-fill" style="height:'+Math.max(10,v/max*120)+'px;border-radius:6px 6px 2px 2px"></div><span class="small muted">'+labels[i]+'</span></div>').join('')+'</div>';}
  function renderAnalytics(s){const month=new Date().getMonth();const monthly=s.appointments.filter(a=>Number(a.date.slice(5,7))===month+1).length;const resolved=s.queries.filter(q=>q.status==='Resolved').length;return '<div class="grid stats">'+stat('Appointments this month',monthly,'Saved clinic records','▦')+stat('New patients',s.patients.filter(p=>p.registered.slice(0,7)===today().slice(0,7)).length,'This month','♧')+stat('Resolved queries',resolved,'All recorded queries','✓')+stat('Pending appointments',s.appointments.filter(a=>a.status==='Pending').length,'Need review','◷')+'</div><div class="grid two-col">'+card('Appointments by date',bars(['Mon','Tue','Wed','Thu','Fri','Sat'],[7,10,8,13,9,5]))+card('Patient registrations',bars(['May','Jun','Jul','Aug','Sep','Oct'],[19,28,22,37,31,s.patients.length]))+card('Appointment status',s.appointments.reduce((html,a)=>html+'<div class="bar-row"><span>'+escapeHtml(a.status)+'</span><div class="bar-bg"><div class="bar-fill" style="width:40%"></div></div><strong>1</strong></div>',''))+card('Query volume',bars(['May','Jun','Jul','Aug','Sep','Oct'],[14,18,13,21,17,s.queries.length]))+'</div>';}
  function renderAppointmentList(items,role){const rows=items.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,7);return '<div class="list">'+(rows.map((a)=>'<div class="list-item" style="align-items:center"><div class="row" style="flex:1"><div class="stat-icon" style="width:44px;height:44px;font-size:11px">'+escapeHtml((a.time||'').split(' ')[0])+'</div><div><div style="font-weight:650">'+escapeHtml(role==='patient'?a.doctor:a.patient)+'</div><div class="muted small">'+escapeHtml(a.department)+' · '+escapeHtml(a.date)+' · '+escapeHtml(a.time)+'</div></div></div>'+badge(a.status)+(role==='reception'&&a.status==='Pending'?'<button class="btn ghost" data-action="review" data-id="'+escapeHtml(a.id)+'">Review</button>':'')+'</div>').join('')||'<div class="empty">No appointments to show.</div>')+'</div>';}
  const tableDefinitions={
    patients:{headers:['Patient','Contact','Department','Registered','Status'],cells:(x)=>[person(x.name,x.id),x.phone||x.email,x.department||'—',x.registered,badge(x.status)]},
    doctors:{headers:['Doctor','Specialty','Department','Patients','Status'],cells:(x)=>[person(x.name,x.id),x.specialty,x.department,x.patients,badge(x.status)]},
    receptionists:{headers:['Receptionist','Contact','Shift','Status'],cells:(x)=>[person(x.name,x.id),x.phone,x.shift,badge(x.status)]},
    appointments:{headers:['Appointment','Patient','Doctor','Date & time','Status'],cells:(x)=>['<strong>'+escapeHtml(x.id)+'</strong>',escapeHtml(x.patient),escapeHtml(x.doctor),escapeHtml(x.date)+'<br><span class="muted small">'+escapeHtml(x.time)+'</span>',badge(x.status)]},
    departments:{headers:['Department','Lead clinician','Doctors','Description'],cells:(x)=>['<strong>'+escapeHtml(x.name)+'</strong>',escapeHtml(x.head||'—'),escapeHtml(x.doctors),escapeHtml(x.description)]},
    prescriptions:{headers:['Prescription','Patient','Doctor','Date','Status'],cells:(x)=>['<strong>'+escapeHtml(x.id)+'</strong>',escapeHtml(x.patient),escapeHtml(x.doctor),escapeHtml(x.date),badge(x.status)]},
    queries:{headers:['Conversation','Patient','Category','Updated','Status'],cells:(x)=>['<strong>'+escapeHtml(x.subject)+'</strong>',escapeHtml(x.patient),escapeHtml(x.category),escapeHtml(x.updated),badge(x.status)]}
  };
  function renderCollectionTable(key,rows,role){const def=tableDefinitions[key];const needle=state.search.toLowerCase();const filtered=(rows||[]).filter(x=>JSON.stringify(x).toLowerCase().includes(needle)).filter(x=>state.filter==='All'||x.status===state.filter);const statuses=Array.from(new Set((rows||[]).map(x=>x.status).filter(Boolean)));return '<div class="card"><div class="toolbar"><input class="input search-input" style="max-width:340px" placeholder="Search '+key+'" value="'+escapeHtml(state.search)+'"><select class="select status-filter" style="max-width:170px"><option>All</option>'+statuses.map(v=>'<option '+(state.filter===v?'selected':'')+'>'+escapeHtml(v)+'</option>').join('')+'</select><span class="muted small" style="margin-left:auto">'+filtered.length+' records</span></div><div class="table-wrap"><table><thead><tr>'+def.headers.map(h=>'<th>'+h+'</th>').join('')+'<th>Action</th></tr></thead><tbody>'+(filtered.map(x=>'<tr>'+def.cells(x).map(v=>'<td>'+v+'</td>').join('')+'<td>'+rowActions(key,x,role)+'</td></tr>').join('')||'<tr><td colspan="'+(def.headers.length+1)+'" class="empty">No records found.</td></tr>')+'</tbody></table></div></div>';}
  function rowActions(key,item,role){let out='<button class="btn ghost" data-action="view" data-type="'+key+'" data-id="'+escapeHtml(item.id)+'" title="Open record">◉</button>';
    if(role==='admin'&&['doctors','receptionists','departments','patients'].includes(key))out+='<button class="btn ghost" data-action="edit" data-type="'+key+'" data-id="'+escapeHtml(item.id)+'" title="Edit record">✎</button>';
    if(role==='admin'&&['doctors','receptionists'].includes(key))out+='<button class="btn ghost" data-action="toggle-user" data-type="'+key+'" data-id="'+escapeHtml(item.id)+'" title="Activate or deactivate">♢</button>';
    if(role==='admin'&&key==='departments')out+='<button class="btn ghost danger" data-action="delete-department" data-id="'+escapeHtml(item.id)+'" data-name="'+escapeHtml(item.name)+'" title="Delete department">×</button>';
    if(role==='reception'&&key==='patients'&&item.status==='Pending')out+='<button class="btn ghost" data-action="verify-patient" data-id="'+escapeHtml(item.id)+'" title="Verify registration">✓</button>';
    if(role==='doctor'&&key==='patients')out+='<a class="btn ghost" href="/doctor/patients/'+encodeURIComponent(item.id)+'" data-route="/doctor/patients/'+encodeURIComponent(item.id)+'">Open</a>';
    if(role==='reception'&&key==='appointments'&&item.status==='Pending')out+='<button class="btn ghost" data-action="review" data-id="'+escapeHtml(item.id)+'" title="Review request">✓</button>';
    if(role==='doctor'&&key==='appointments'&&item.status==='Confirmed')out+='<button class="btn ghost" data-action="complete" data-id="'+escapeHtml(item.id)+'" title="Complete appointment">✓</button><a class="btn ghost" href="/doctor/consultation" data-route="/doctor/consultation">Consult</a>';
    if(role==='reception'&&key==='prescriptions'&&item.status==='Awaiting processing')out+='<button class="btn ghost" data-action="process" data-id="'+escapeHtml(item.id)+'" title="Complete processing">✓</button>';
    if(key==='queries')out+='<button class="btn ghost" data-action="open-query" data-id="'+escapeHtml(item.id)+'" title="Open conversation">→</button>';
    return out;
  }
  function renderPrescriptionList(items,role){return '<div class="list">'+(items.map(rx=>'<article class="card" style="box-shadow:none;margin-bottom:12px"><div class="row between"><div><div class="row"><span style="color:#147d83">▤</span><strong>'+escapeHtml(rx.id)+'</strong>'+badge(rx.status)+'</div><div class="muted small" style="margin-top:8px">'+escapeHtml(rx.patient)+' · '+escapeHtml(rx.doctor)+' · '+escapeHtml(rx.date)+'</div></div><button class="btn" data-action="print">▣ Print</button></div><div style="margin-top:16px;background:#f8fafb;padding:13px;border-radius:6px"><strong>'+escapeHtml(rx.diagnosis)+'</strong>'+(rx.items||[]).map(item=>'<div class="row between small" style="margin-top:9px"><span><strong>'+escapeHtml(item.medicine)+'</strong> · '+escapeHtml(item.dosage)+'</span><span class="muted">'+escapeHtml(item.frequency)+' · '+escapeHtml(item.duration)+' · '+escapeHtml(item.food)+'</span></div>').join('')+'<p class="muted small">'+escapeHtml((rx.items||[])[0]?.instructions||'')+'</p></div>'+(role==='reception'&&rx.status==='Awaiting processing'?'<button class="btn primary" style="margin-top:13px" data-action="process" data-id="'+escapeHtml(rx.id)+'">✓ Mark processing complete</button>':'')+'</article>').join('')||'<div class="empty">No prescriptions available.</div>')+'</div>';}
  function renderNotifications(items,role,full){const list=full?items:items.filter(n=>n.role===role).slice(0,4);return '<div class="list">'+(list.map(n=>'<div class="list-item" style="align-items:center"><div class="stat-icon" style="width:36px;height:36px">♧</div><div style="flex:1"><div style="font-weight:'+(n.read?'500':'700')+'">'+escapeHtml(n.message)+'</div><div class="muted small" style="margin-top:4px">'+escapeHtml(n.date)+' · '+escapeHtml(n.type)+'</div></div>'+(!n.read?badge('New'):'')+'<button class="btn ghost" data-action="read" data-id="'+escapeHtml(n.id)+'" title="Mark as read">✓</button></div>').join('')||'<div class="empty">You’re all caught up.</div>')+'</div>';}
  function renderQueryList(items){return '<div class="list">'+(items.map(q=>'<button data-action="open-query" data-id="'+escapeHtml(q.id)+'" class="list-item" style="width:100%;text-align:left;background:transparent;border:0"><div class="avatar">'+initials(q.patient)+'</div><div style="flex:1;min-width:0"><div class="row between"><strong>'+escapeHtml(q.subject)+'</strong>'+badge(q.status)+'</div><div class="muted small">'+escapeHtml(q.patient)+' · '+escapeHtml(q.category)+'</div><div class="muted small" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escapeHtml(q.messages?.at(-1)?.text||'')+'</div></div></button>').join('')||'<div class="empty">No conversations found.</div>')+'</div>';}
  function renderQueries(items,role){if(role==='patient')return '<div class="grid two-col"><section class="card"><h2 class="section-title">Your conversations</h2>'+renderQueryList(items)+'<form data-form="new-query" style="margin-top:22px;border-top:1px solid #edf1f3;padding-top:17px"><h3 class="section-title">Ask the care team</h3>'+field('Subject','<input class="input" name="subject" required maxlength="200" placeholder="What do you need help with?">')+field('Category','<select class="select" name="category"><option>Appointments</option><option>Medication</option><option>Medical question</option><option>Billing</option><option>Other</option></select>')+field('Message','<textarea class="textarea" name="message" required maxlength="4000"></textarea>')+'<button class="btn primary">Send query</button></form></section><section class="card">'+renderConversation(items.find(q=>q.id===state.selected),role)+'</section></div>';return '<div class="grid two-col"><section class="card"><div class="toolbar"><input class="input search-input" placeholder="Search conversations" value="'+escapeHtml(state.search)+'"></div>'+renderQueryList(items)+'</section><section class="card">'+renderConversation(items.find(q=>q.id===state.selected),role)+'</section></div>';}
  function renderConversation(q,role){if(!q)return '<div class="empty"><div class="empty-icon">▱</div>Select a conversation to view messages.</div>';const messages=(q.messages||[]).map(m=>'<div style="align-self:'+(String(m.role).toLowerCase()==='patient'?'flex-start':'flex-end')+';max-width:85%;background:'+(String(m.role).toLowerCase()==='patient'?'white':'#e4f4f2')+';padding:11px;border-radius:8px"><div class="muted small">'+escapeHtml(m.from||m.senderName||'Clinic team')+' · '+escapeHtml(new Date(m.date).toLocaleString())+'</div><div style="margin-top:5px;line-height:1.5">'+escapeHtml(m.text)+'</div></div>').join('');return '<div class="row between" style="margin-bottom:10px"><div><h3 style="margin:0 0 5px">'+escapeHtml(q.subject)+'</h3>'+badge(q.status)+'</div>'+(role==='reception'?'<div><button class="btn" data-action="forward" data-id="'+escapeHtml(q.id)+'">Forward</button> <button class="btn" data-action="resolve" data-id="'+escapeHtml(q.id)+'">Resolve</button></div>':'')+'</div><div style="height:340px;overflow:auto;background:#f7fafb;border-radius:8px;padding:13px;display:flex;flex-direction:column;gap:12px">'+messages+'</div>'+(q.status!=='Resolved'?'<form data-form="reply-query" data-id="'+escapeHtml(q.id)+'" style="display:flex;gap:8px;margin-top:12px"><input class="input" name="message" required maxlength="4000" placeholder="Write a reply…"><button class="btn primary">Send</button></form>':'')+'<p class="muted" style="font-size:10px">Administrative replies cannot provide medical diagnosis or change prescriptions.</p>';}

  function field(label,control){return '<div class="field"><label>'+label+'</label>'+control+'</div>';}
  function renderAppointmentForm(s){return '<div class="card" style="max-width:720px"><h2 class="section-title">Appointment details</h2><form data-form="appointment"><div class="grid two-col">'+field('Department','<select class="select" name="department" required>'+s.departments.map(d=>'<option>'+escapeHtml(d.name)+'</option>').join('')+'</select>')+field('Doctor','<select class="select" name="doctor" required>'+s.doctors.filter(d=>d.status==='Active').map(d=>'<option>'+escapeHtml(d.name)+'</option>').join('')+'</select>')+field('Preferred date','<input class="input" type="date" name="date" min="'+today()+'" required>')+field('Available time slot','<select class="select" name="time">'+['09:00 AM','09:30 AM','10:00 AM','10:30 AM','11:00 AM','01:30 PM','02:00 PM','02:30 PM','03:00 PM'].map(t=>'<option>'+t+'</option>').join('')+'</select>')+'</div>'+field('Reason for visit','<input class="input" name="reason" required maxlength="500" placeholder="Briefly describe what you need help with">')+field('Additional notes','<textarea class="textarea" name="notes" maxlength="1500"></textarea>')+'<div class="row"><button class="btn primary">▦ Send request</button><span class="muted small">Your request will be confirmed by reception.</span></div></form></div>';}
  function renderPatientForm(s){return '<div class="card" style="max-width:900px"><div class="row" style="margin-bottom:17px;color:#147d83">♢ <span class="small">Registration details are saved to the clinic database for review.</span></div><form data-form="patient-staff"><div class="grid two-col">'+field('Full name','<input class="input" name="name" required maxlength="160">')+field('Date of birth','<input class="input" type="date" name="dob" required>')+field('Gender','<select class="select" name="gender" required><option value="">Select</option><option>Female</option><option>Male</option><option>Non-binary</option><option>Prefer not to say</option></select>')+field('Phone','<input class="input" name="phone" type="tel" required minlength="7">')+field('Email','<input class="input" type="email" name="email" required>')+field('Patient portal password','<input class="input" type="password" name="password" minlength="12" required>')+field('Blood group','<select class="select" name="blood"><option value="">Select</option>'+['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(x=>'<option>'+x+'</option>').join('')+'</select>')+field('Department','<select class="select" name="departmentId"><option value="">General / not assigned</option>'+s.departments.map(d=>'<option value="'+escapeHtml(d.id)+'">'+escapeHtml(d.name)+'</option>').join('')+'</select>')+field('Address','<input class="input" name="address" maxlength="400">')+field('Emergency contact','<input class="input" name="emergency" maxlength="240">')+field('Basic identification details','<input class="input" name="identification" maxlength="100">')+'</div><button class="btn primary">＋ Create patient record</button></form></div>';}
  function renderConsultationForm(s,assignedAppointments){const patients=s.patients;return '<form class="card" style="max-width:950px" data-form="consultation"><div class="grid two-col">'+field('Patient','<select class="select" name="patientId" required>'+patients.map(p=>'<option value="'+escapeHtml(p.id)+'">'+escapeHtml(p.name)+'</option>').join('')+'</select>')+field('Appointment','<select class="select" name="appointmentId"><option value="">Walk-in / prior assignment</option>'+assignedAppointments.filter(a=>a.status==='Confirmed'||a.status==='Completed').map(a=>'<option value="'+escapeHtml(a.id)+'">'+escapeHtml(a.id)+' · '+escapeHtml(a.patient)+' · '+escapeHtml(a.date)+'</option>').join('')+'</select>')+'</div><div class="grid two-col">'+field('Symptoms','<textarea class="textarea" name="symptoms" required maxlength="3000"></textarea>')+field('Diagnosis','<textarea class="textarea" name="diagnosis" required maxlength="2000"></textarea>')+'</div>'+field('Clinical notes','<textarea class="textarea" name="notes" maxlength="5000"></textarea>')+field('Follow-up recommendation','<input class="input" name="followup" maxlength="500" value="4 weeks">')+'<h3 class="section-title">Prescription</h3><div class="grid three-col">'+field('Medicine','<input class="input" name="medicine" placeholder="Use formulary medicine name">')+field('Dosage','<input class="input" name="dosage" placeholder="e.g. 10 mg">')+field('Frequency','<select class="select" name="frequency"><option>Once daily</option><option>Twice daily</option><option>Three times daily</option><option>As needed</option></select>')+field('Duration','<input class="input" name="duration" value="7 days">')+field('Before / after food','<select class="select" name="food"><option>After food</option><option>Before food</option><option>With food</option><option>Any time</option></select>')+field('Instructions','<input class="input" name="instructions">')+'</div><button class="btn primary">✓ Save consultation & submit prescription</button></form>';}
  function renderBilling(s){return '<div class="grid two-col"><section class="card"><h2 class="section-title">Create receipt</h2><form data-form="bill">'+field('Patient','<select class="select" name="patientId">'+s.patients.map(p=>'<option value="'+escapeHtml(p.id)+'">'+escapeHtml(p.name)+'</option>').join('')+'</select>')+'<div class="grid two-col">'+field('Registration fee ($)','<input class="input" type="number" name="registration" min="0" step="0.01" value="0">')+field('Consultation fee ($)','<input class="input" type="number" name="consultation" min="0" step="0.01" value="85">')+field('Other charges ($)','<input class="input" type="number" name="other" min="0" step="0.01" value="0">')+'</div><button class="btn primary">▤ Create receipt</button></form></section>'+card('Recent receipts','<div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Patient</th><th>Date</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody>'+s.bills.map(b=>'<tr><td>'+escapeHtml(b.id)+'</td><td>'+escapeHtml(b.patient)+'</td><td>'+escapeHtml(b.date)+'</td><td>$'+(b.registration+b.consultation+b.other).toFixed(2)+'</td><td>'+badge(b.status)+'</td><td>'+(b.status==='Pending'?'<button class="btn ghost" data-action="pay" data-id="'+escapeHtml(b.id)+'">✓ Paid</button>':'')+' <button class="btn ghost" data-action="print">▣</button></td></tr>').join('')+'</tbody></table></div>')+'</div>';}
  function renderSettings(s){const d=s.settings||{};return '<div class="grid two-col"><section class="card"><h2 class="section-title">Clinic information</h2><form data-form="settings">'+field('Clinic name','<input class="input" name="clinicName" required value="'+escapeHtml(d.clinicName||'')+'">')+field('Address','<input class="input" name="address" value="'+escapeHtml(d.address||'')+'">')+field('Phone','<input class="input" name="phone" value="'+escapeHtml(d.phone||'')+'">')+field('Email','<input class="input" type="email" name="email" value="'+escapeHtml(d.email||'')+'">')+'<button class="btn primary">Save changes</button></form></section>'+card('Preferences','<div class="list">'+[['Appointment reminders','Notify patients before scheduled visits'],['Prescription updates','Send a notice when prescriptions are ready'],['Weekly activity summary','A summary for clinic administrators']].map(x=>'<label class="row between" style="padding:9px 0;border-bottom:1px solid #edf1f3"><span><strong>'+x[0]+'</strong><div class="muted small">'+x[1]+'</div></span><input type="checkbox" checked></label>').join('')+field('Default appointment duration','<select class="select"><option>30 minutes</option><option>20 minutes</option><option>45 minutes</option></select>')+'</div>')+'</div>';}
  function renderProfile(role,s){const person=role==='patient'?s.patients.find(x=>x.email===state.user.email):role==='doctor'?s.doctors.find(x=>x.email===state.user.email):s.receptionists.find(x=>x.email===state.user.email);return '<div class="grid two-col">'+card('Personal information','<div class="person" style="margin-bottom:24px"><div class="avatar" style="width:54px;height:54px;font-size:16px">'+initials(state.user.name)+'</div><div><strong>'+escapeHtml(state.user.name)+'</strong><div class="muted small">'+(role==='reception'?'Receptionist':role)+'</div></div></div><div class="grid two-col">'+[['Email',state.user.email],['Phone',person?.phone||'—'],['Department',person?.department||person?.specialty||'—'],['Status',person?.status||'Active']].map(x=>'<div style="padding:12px 0;border-bottom:1px solid #edf1f3"><div class="muted small">'+x[0]+'</div><strong>'+escapeHtml(x[1])+'</strong></div>').join('')+'</div><button class="btn" data-action="edit-profile" style="margin-top:20px">✎ Edit phone</button>')+card('Account security','<p class="muted">Your session is protected by a secure, HTTP-only cookie.</p><button class="btn danger" data-action="logout">↪ Sign out</button>')+'</div>';}
  function renderPatientDetail(id,s){const p=s.patients.find(x=>x.id===id);if(!p)return '<div class="card empty">Patient record not found.</div>';return '<div class="grid two-col">'+card('Patient overview','<div class="person" style="margin-bottom:20px"><div class="avatar" style="width:54px;height:54px">'+initials(p.name)+'</div><div><h2>'+escapeHtml(p.name)+'</h2><span class="muted small">'+escapeHtml(p.id)+' · '+escapeHtml(p.gender)+' · '+escapeHtml(p.dob)+'</span></div></div><div class="grid two-col">'+[['Phone',p.phone],['Email',p.email],['Blood group',p.blood],['Emergency contact',p.emergency],['Address',p.address],['Registered',p.registered]].map(x=>'<div class="list-item"><span class="muted">'+x[0]+'</span><strong>'+escapeHtml(x[1]||'—')+'</strong></div>').join('')+'</div>')+card('Recent consultations',s.consultations.filter(c=>c.patientId===id).map(c=>'<div class="list-item"><div><strong>'+escapeHtml(c.diagnosis)+'</strong><div class="muted small">'+escapeHtml(c.date)+' · '+escapeHtml(c.symptoms)+'</div><p class="small">'+escapeHtml(c.notes)+'</p></div></div>').join('')||'<div class="empty">No consultation history yet.</div>')+card('Prescription history',s.prescriptions.filter(rx=>rx.patientId===id).map(rx=>'<div class="list-item"><div><strong>'+escapeHtml(rx.id)+' · '+escapeHtml(rx.diagnosis)+'</strong><div class="muted small">'+escapeHtml(rx.date)+' · '+escapeHtml(rx.items.map(i=>i.medicine).join(', '))+'</div></div>'+badge(rx.status)+'</div>').join('')||'<div class="empty">No prescriptions recorded.</div>')+'</div>';}

  function modalFields(type,selected){const value=(key,fallback)=>escapeHtml(selected&&selected[key]!==undefined?selected[key]:fallback||'');
    if(type==='appointments')return field('Patient','<select class="select" name="patientId" required>'+state.store.patients.map(p=>'<option value="'+escapeHtml(p.id)+'" '+(selected&&p.id===selected.patientId?'selected':'')+'>'+escapeHtml(p.name)+'</option>').join('')+'</select>')+field('Department','<select class="select" name="department">'+state.store.departments.map(d=>'<option '+(value('department')===d.name?'selected':'')+'>'+escapeHtml(d.name)+'</option>').join('')+'</select>')+field('Doctor','<select class="select" name="doctor">'+state.store.doctors.map(d=>'<option '+(value('doctor')===d.name?'selected':'')+'>'+escapeHtml(d.name)+'</option>').join('')+'</select>')+'<div class="grid two-col">'+field('Date','<input class="input" type="date" name="date" required value="'+value('date',today())+'">')+field('Time','<select class="select" name="time">'+['09:00 AM','09:30 AM','10:00 AM','10:30 AM','11:00 AM','01:30 PM','02:00 PM','02:30 PM','03:00 PM'].map(t=>'<option '+(value('time')===t?'selected':'')+'>'+t+'</option>').join('')+'</select>')+'</div>'+field('Reason','<input class="input" name="reason" required value="'+value('reason')+'">')+field('Status','<select class="select" name="status">'+['Pending','Confirmed','Rescheduled','Rejected','Cancelled','Completed'].map(v=>'<option '+(value('status')===v?'selected':'')+'>'+v+'</option>').join('')+'</select>');
    if(type==='patients')return field('Full name','<input class="input" name="name" required value="'+value('name')+'">')+field('Email','<input class="input" name="email" type="email" required value="'+value('email')+'">')+field('Phone','<input class="input" name="phone" value="'+value('phone')+'">')+field('Date of birth','<input class="input" type="date" name="dob" value="'+value('dob')+'">')+field('Gender','<input class="input" name="gender" value="'+value('gender')+'">')+field('Blood group','<input class="input" name="blood" value="'+value('blood')+'">')+field('Address','<input class="input" name="address" value="'+value('address')+'">')+field('Emergency contact','<input class="input" name="emergency" value="'+value('emergency')+'">')+field('Identification details','<input class="input" name="identification" value="'+value('identification')+'">')+field('Department','<select class="select" name="departmentId"><option value="">Unassigned</option>'+state.store.departments.map(d=>'<option value="'+escapeHtml(d.id)+'" '+(d.name===value('department')?'selected':'')+'>'+escapeHtml(d.name)+'</option>').join('')+'</select>')+field('Patient portal password'+(selected?' (leave blank to keep existing)':''),'<input class="input" type="password" name="password" '+(selected?'':'required minlength="12"')+' minlength="12" autocomplete="new-password">')+(selected?field('Status','<select class="select" name="status">'+['Pending','Verified','Active','Inactive'].map(v=>'<option '+(value('status')===v?'selected':'')+'>'+v+'</option>').join('')+'</select>'):'');
    if(type==='doctors')return field('Name','<input class="input" name="name" required value="'+value('name')+'">')+field('Email','<input class="input" type="email" name="email" required value="'+value('email')+'">')+field('Password (12+ characters)','<input class="input" type="password" name="password" '+(selected?'':'required')+' minlength="12">')+field('Phone','<input class="input" name="phone" value="'+value('phone')+'">')+field('Specialty','<input class="input" name="specialty" value="'+value('specialty')+'">')+field('Department','<select class="select" name="department">'+state.store.departments.map(d=>'<option '+(value('department')===d.name?'selected':'')+'>'+escapeHtml(d.name)+'</option>').join('')+'</select>')+field('Experience','<input class="input" name="experience" value="'+value('experience')+'">')+field('Status','<select class="select" name="status"><option>Active</option><option '+(value('status')==='On leave'?'selected':'')+'>On leave</option></select>');
    if(type==='receptionists')return field('Name','<input class="input" name="name" required value="'+value('name')+'">')+field('Email','<input class="input" type="email" name="email" required value="'+value('email')+'">')+field('Password (12+ characters)','<input class="input" type="password" name="password" '+(selected?'':'required')+' minlength="12">')+field('Phone','<input class="input" name="phone" value="'+value('phone')+'">')+field('Shift','<select class="select" name="shift"><option>Morning</option><option>Evening</option><option>Night</option></select>')+field('Status','<select class="select" name="status"><option>Active</option><option>Inactive</option></select>');
    if(type==='departments')return field('Department name','<input class="input" name="name" required value="'+value('name')+'">')+field('Head clinician','<select class="select" name="head"><option value="">Not assigned</option>'+state.store.doctors.map(d=>'<option '+(value('head')===d.name?'selected':'')+'>'+escapeHtml(d.name)+'</option>').join('')+'</select>')+field('Description','<textarea class="textarea" name="description">'+value('description')+'</textarea>');
    return '';
  }
  function renderModal(){if(!state.modal)return '';const modal=state.modal;const item=modal.id?findItem(modal.type,modal.id):null;let body='';let title='Record details';
    if(modal.kind==='appointment'){title='Review appointment request';body='<form data-form="review" data-id="'+escapeHtml(modal.id)+'"><p><strong>'+escapeHtml(item?.patient||'')+'</strong> · '+escapeHtml(item?.department||'')+'</p><p class="muted">'+escapeHtml(item?.reason||'')+'</p>'+field('Assign clinician','<select class="select" name="doctor">'+state.store.doctors.filter(d=>d.status==='Active'&&d.department===item?.department).map(d=>'<option '+(d.name===item?.doctor?'selected':'')+'>'+escapeHtml(d.name)+'</option>').join('')+'</select>')+field('Choose outcome','<select class="select" name="status"><option>Confirmed</option><option>Rescheduled</option><option>Rejected</option></select>')+field('New date (if rescheduled)','<input class="input" type="date" name="date" value="'+escapeHtml(item?.date||'')+'">')+'<div class="row" style="justify-content:end"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary">Save decision</button></div></form>';}
    else if(modal.kind==='create'||modal.kind==='edit'){title=(modal.kind==='create'?'Add ':'Edit ')+(titles[modal.type]||'record').replace(' management','').toLowerCase();body='<form data-form="record" data-kind="'+modal.kind+'" data-type="'+modal.type+'">'+modalFields(modal.type,item)+'<div class="row" style="justify-content:end"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary">Save</button></div></form>';}
    else if(modal.kind==='view'){title='View '+(titles[modal.type]||'record').toLowerCase();body='<pre style="white-space:pre-wrap;overflow:auto">'+escapeHtml(JSON.stringify(item,null,2))+'</pre><button class="btn" data-action="close-modal">Close</button>';}
    else if(modal.kind==='edit-profile'){title='Update your phone number';const person=state.user.role==='PATIENT'?state.store.patients.find(x=>x.email===state.user.email):state.user.role==='DOCTOR'?state.store.doctors.find(x=>x.email===state.user.email):state.store.receptionists.find(x=>x.email===state.user.email);body='<form data-form="profile">'+field('Phone','<input class="input" name="phone" value="'+escapeHtml(person?.phone||'')+'" required>')+'<button class="btn primary">Save changes</button> <button class="btn" type="button" data-action="close-modal">Cancel</button></form>';}
    return '<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="'+escapeHtml(title)+'"><div class="modal-head"><h2>'+escapeHtml(title)+'</h2><button class="btn ghost" data-action="close-modal" aria-label="Close">×</button></div>'+body+'</section></div>';
  }
  function findItem(type,id){return (state.store[type]||[]).find(item=>item.id===id);}
  function formValues(form){return Object.fromEntries(new FormData(form).entries());}
  async function handleSubmit(event){const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const type=form.dataset.form;const values=formValues(form);const button=form.querySelector('button[type="submit"],button:not([type])');if(button){button.disabled=true;button.dataset.label=button.textContent;button.textContent='Saving…';}
    try{
      if(type==='login'){const result=await api('/auth/login',{method:'POST',body:values});state.user=result.user;await reloadStore();navTo('/'+state.user.role.toLowerCase()+'/dashboard');return;}
      if(type==='register'){const result=await api('/auth/register',{method:'POST',body:values});state.user=result.user;navTo('/patient/dashboard');notify('Your patient account was created.');return;}
      if(type==='appointment'){await api('/appointments',{method:'POST',body:{...values,departmentId:undefined}});navTo('/patient/appointments');notify('Appointment request sent to the front desk.');return;}
      if(type==='patient-staff'){const id='PT-'+crypto.randomUUID().slice(0,8).toUpperCase();const changes=[{collection:'patients',id,action:'create',data:values},{collection:'notifications',id:'NT-'+crypto.randomUUID(),action:'create',data:{role:'ADMIN',message:'New patient registration for '+values.name+' needs verification',type:'Registration',related:id}}];await saveChanges(changes,'Patient record created for verification.');return;}
      if(type==='consultation'){const body={patientId:values.patientId,appointmentId:values.appointmentId||undefined,symptoms:values.symptoms,diagnosis:values.diagnosis,notes:values.notes,followup:values.followup,items:values.medicine&&values.dosage?[{medicine:values.medicine,dosage:values.dosage,frequency:values.frequency,duration:values.duration,food:values.food,instructions:values.instructions}]:[]};await api('/consultations',{method:'POST',body});await reloadStore();render();notify('Consultation and any prescription were saved.');return;}
      if(type==='new-query'){const body={subject:values.subject,category:values.category,messages:[{text:values.message}]};const result=await api('/queries',{method:'POST',body});state.selected=result.id;await reloadStore();render();notify('Your query was sent to the clinic.');return;}
      if(type==='reply-query'){await api('/queries/'+encodeURIComponent(form.dataset.id)+'/messages',{method:'POST',body:{message:values.message}});state.selected=form.dataset.id;await reloadStore();render();notify('Reply sent.');return;}
      if(type==='bill'){await api('/bills',{method:'POST',body:values});await reloadStore();render();notify('Receipt created.');return;}
      if(type==='settings'){await saveChanges([{collection:'settings',id:'clinic',action:'update',data:{settings:values}}],'Clinic settings saved.');return;}
      if(type==='profile'){await api('/profile',{method:'PATCH',body:values});await reloadStore();state.modal=null;render();notify('Profile updated.');return;}
      if(type==='review'){await saveAppointmentDecision(form.dataset.id,values);return;}
      if(type==='record'){const collection=form.dataset.type;const kind=form.dataset.kind;let id=state.modal.id;const data={...values};if(collection==='patients'&&data.departmentId){data.department=state.store.departments.find(d=>d.id===data.departmentId)?.name;}if(collection==='patients'&&kind==='create'&&!data.departmentId){delete data.departmentId;}
        if(kind==='create'){id=(collection==='departments'?'DP':collection==='doctors'?'DR':collection==='receptionists'?'RC':'PT')+'-'+crypto.randomUUID().slice(0,8).toUpperCase();await saveChanges([{collection,id,action:'create',data}],(titles[collection]||'Record')+' created.');}else{if(!data.password)delete data.password;await saveChanges([{collection,id,action:'update',data}],(titles[collection]||'Record')+' updated.');}state.modal=null;render();return;}
    }catch(error){const node=form.querySelector('.form-error');if(node)node.textContent=error.message;else notify(error.message);if(button){button.disabled=false;button.textContent=button.dataset.label||'Save';}}
  }
  async function handleClick(event){const route=event.target.closest('[data-route]');if(route){event.preventDefault();navTo(route.dataset.route);return;}
    const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
    try{
      if(action==='close-modal'){state.modal=null;render();return;}
      if(action==='backdrop'&&event.target===target){state.modal=null;render();return;}
      if(action==='mobile'){state.mobile=!state.mobile;render();return;}
      if(action==='theme'){state.theme=!state.theme;localStorage.setItem('mf_dark',state.theme?'1':'0');render();return;}
      if(action==='logout'){await api('/auth/logout',{method:'POST'}).catch(()=>{});state.user=null;state.store=null;navTo('/login');return;}
      if(action==='create'){const page=location.pathname.split('/')[2];const type=page==='patient-registration'?'patients':page;state.modal={kind:'create',type};render();return;}
      if(action==='edit'||action==='view'){state.modal={kind:action,type:target.dataset.type,id:target.dataset.id};render();return;}
      if(action==='review'){state.modal={kind:'appointment',type:'appointments',id:target.dataset.id};render();return;}
      if(action==='slide-next'){showHeroSlide(state.slide+1);return;}
      if(action==='slide-prev'){showHeroSlide(state.slide-1);return;}
      if(action==='slide'){showHeroSlide(Number(target.dataset.slide));return;}
      if(action==='find-doctors'){document.getElementById('care-team')?.scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('doctor-search')?.focus({preventScroll:true});return;}
      if(action==='public-menu'){const nav=app.querySelector('.site-nav');nav?.classList.toggle('is-open');target.setAttribute('aria-expanded',nav?.classList.contains('is-open')?'true':'false');return;}
      if(action==='complete'){await saveChanges([{collection:'appointments',id:target.dataset.id,action:'update',data:{status:'Completed'}}],'Appointment marked complete.');return;}
      if(action==='verify-patient'){await saveChanges([{collection:'patients',id:target.dataset.id,action:'update',data:{status:'Verified'}}],'Patient registration verified.');return;}
      if(action==='toggle-user'){const record=findItem(target.dataset.type,target.dataset.id);await saveChanges([{collection:target.dataset.type,id:target.dataset.id,action:'update',data:{status:record.status==='Active'?'Inactive':'Active'}}],'Account status updated.');return;}
      if(action==='delete-department'){if(!window.confirm('Delete '+target.dataset.name+'? Existing appointments or clinicians may prevent deletion.'))return;await api('/departments/'+encodeURIComponent(target.dataset.id),{method:'DELETE'});await reloadStore();render();notify('Department deleted.');return;}
      if(action==='process'){await api('/prescriptions/'+encodeURIComponent(target.dataset.id)+'/status',{method:'PATCH',body:{status:'Available'}});await reloadStore();render();notify('Prescription processed; patient notified.');return;}
      if(action==='pay'){await api('/bills/'+encodeURIComponent(target.dataset.id)+'/payment-status',{method:'PATCH',body:{status:'Paid'}});await reloadStore();render();notify('Receipt marked paid.');return;}
      if(action==='read'){await api('/notifications/'+encodeURIComponent(target.dataset.id)+'/read',{method:'PATCH',body:{read:true}});await reloadStore();render();return;}
      if(action==='read-all'){const changes=state.store.notifications.filter(n=>!n.read).slice(0,50).map(n=>({collection:'notifications',id:n.id,action:'update',data:{read:true}}));if(changes.length)await saveChanges(changes,'All notifications marked as read.');return;}
      if(action==='open-query'){state.selected=target.dataset.id;render();return;}
      if(action==='forward'||action==='resolve'){const id=target.dataset.id;const status=action==='forward'?'Forwarded to Doctor':'Resolved';await saveChanges([{collection:'queries',id,action:'update',data:{status}}],action==='forward'?'Query forwarded to doctor.':'Query resolved.');state.selected=id;render();return;}
      if(action==='print'){window.print();return;}
      if(action==='edit-profile'){state.modal={kind:'edit-profile'};render();return;}
    }catch(error){notify(error.message);}
  }
  async function saveAppointmentDecision(id,values){const item=findItem('appointments',id);const status=values.status||'Confirmed';const data={status,doctor:values.doctor};if(status==='Rescheduled'){data.date=values.date;data.time=item.time;}await saveChanges([{collection:'appointments',id,action:'update',data}],status==='Rejected'?'Appointment request declined.':'Appointment '+status.toLowerCase()+'.');state.modal=null;render();}
  function handleInput(event){const target=event.target;if(target.matches('.search-input')){state.search=target.value;const active=document.activeElement;const start=active.selectionStart;render();const replacement=app.querySelector('.search-input');if(replacement){replacement.focus();if(start!==null)replacement.setSelectionRange(start,start);}}}
  function handleChange(event){if(event.target.matches('.status-filter')){state.filter=event.target.value;render();}}

  app.addEventListener('click',handleClick);
  app.addEventListener('submit',handleSubmit);
  app.addEventListener('input',handleInput);
  app.addEventListener('change',handleChange);
  window.addEventListener('popstate',render);
  function showHeroSlide(index){state.slide=(index+slides.length)%slides.length;const item=slides[state.slide];const image=document.getElementById('hero-image');if(!image)return;image.src=item.image;image.alt=item.eyebrow;document.getElementById('hero-eyebrow').textContent=item.eyebrow;document.getElementById('hero-title').innerHTML=item.title;document.getElementById('hero-copy').textContent=item.copy;document.getElementById('hero-label').textContent=item.label;document.getElementById('hero-count').textContent='0'+(state.slide+1);document.querySelectorAll('.site-hero-dots button').forEach((button,i)=>button.classList.toggle('active',i===state.slide));}
  render().catch((error) => {
    console.error('MediFlow startup failed while rendering ' + location.pathname, error);
    const pathname = decodeURIComponent(location.pathname);
    const isPublicPage = pathname === '/' || ['/about','/doctors','/departments','/services','/expertise','/patients','/contact'].includes(pathname);
    try {
      if (isPublicPage) renderLanding([], []);
      else renderLogin('The page could not be loaded. Please refresh and try again.');
    } catch (fallbackError) {
      console.error('MediFlow startup fallback failed', fallbackError);
      app.textContent = 'MediFlow could not start. Please refresh the page.';
    }
  });
}());
